-- Yevgeni's restaurant: seed for Supabase / Neon (PostgreSQL)
CREATE TABLE customers (id integer PRIMARY KEY, name text NOT NULL, city text, joined date, email text);
CREATE TABLE dishes (id integer PRIMARY KEY, name text NOT NULL, category text NOT NULL, price numeric(8,2) NOT NULL, cost numeric(8,2) NOT NULL);
CREATE TABLE couriers (id integer PRIMARY KEY, name text NOT NULL, vehicle text);
CREATE TABLE orders (id integer PRIMARY KEY, customer_id integer, courier_id integer, order_ts timestamp NOT NULL, channel text NOT NULL, delivery_min integer, rating integer, tip numeric(8,2), status text NOT NULL);
CREATE TABLE order_items (order_id integer NOT NULL, dish_id integer NOT NULL, qty integer NOT NULL, PRIMARY KEY (order_id, dish_id));
CREATE TABLE app_events (id integer PRIMARY KEY, order_id integer, event_ts timestamp, payload jsonb);

